$('av-hex').addEventListener('input',e=>{let v=e.target.value.trim();if(v[0]!=='#')v='#'+v;if(/^#[0-9a-f]{6}$/i.test(v)){ad.color=v.toLowerCase();hsv=hexToHsv(ad.color);drawAv()}});
